#pragma once
// Generative heal: fills a brush stroke (or a round spot) with content generated by an
// inpainting model (LaMa). Works in sensor space on linear camera data, before every other
// edit. LaMa works at 512x512, so large areas come out softer: their size is capped.

#include "Develop.h"
#include "Image.h"
#include "RawDecoder.h"

#include <QByteArray>
#include <QMap>
#include <QRect>

namespace silma {

// Largest heal: the stroke's extent including the brush, relative to the sensor's long edge.
constexpr double kMaxHealExtent = 0.2;

// Extent of a heal (the larger side of its bounding box including the brush), relative to
// the sensor's long edge.
double healExtent(const HealSpot& spot, int sensorWidth, int sensorHeight);

struct HealPatch {
    QRect rect; // full-resolution sensor pixels
    ImageF data; // linear camera RGB (white-balanced as decoded), rect-sized
};

// Generates the fill for a spot from a full-resolution raw. Throws on failure.
HealPatch generateHealPatch(const RawImage& raw, const HealSpot& spot, QString* providerUsed = nullptr);

QByteArray encodePatchData(const ImageF& img);
ImageF decodePatchData(const QByteArray& data, int width, int height);

// Pastes a patch into an image covering the whole sensor at `scale` (1 = full res,
// 0.5 = half-size decode), feathered around the stroke.
void pasteHealPatch(ImageF& img, double scale, int sensorWidth, int sensorHeight, const HealSpot& spot, const HealPatch& patch);

class Batch;
class DevelopEngine;

// Batch storage of patches.
qint64 storeHealPatch(Batch& b, qint64 photoId, const HealPatch& p);
QMap<qint64, HealPatch> loadHealPatches(Batch& b, const DevelopSettings& s);
void addHealPatches(DevelopEngine& e, const QMap<qint64, HealPatch>& patches);

} // namespace silma
